                "handle": "unused",
                "public_key": wrong,
                "encrypted_material": "unused",
            }
        result = self._mint(algorithm, public_key, raw_material)
        return {
            "handle": result["handle"],
            "public_key": result["public_key"],
            "encrypted_material": result["encrypted_material"],
        }

